module hunter_exam (\n    input clk,\n    input rst_n,\n    input start,\n    output reg done,\n    output reg [63:0] result_max\n);\n\nlocalparam C = 3'd5;\nlocalparam K = 30'd2;\n\n// State declarations\nlocalparam [2:0] S_IDLE   = 3'd0;\nlocalparam [2:0] S_CHECK  = 3'd1;\nlocalparam [2:0] S_MULT1  = 3'd2;\nlocalparam [2:0] S_MULT1A = 3'd3;\nlocalparam [2:0] S_MULT2  = 3'd4;\nlocalparam [2:0] S_MULT2A = 3'd5;\nlocalparam [2:0] S_DONE   = 3'd6;\n\nreg [2:0] state;\nreg [4:0] index;\nwire [29:0] k_bits = K;\n\n// Matrix declarations\nreg signed [63:0] result [0:4][0:4];\nreg signed [63:0] base [0:4][0:4];\nreg signed [63:0] mult_A [0:4][0:4];\nreg signed [63:0] mult_B [0:4][0:4];\nreg signed [63:0] mult_out [0:4][0:4];\n\n// Hardcoded A matrix values\nwire signed [63:0] A [0:4][0:4];\nassign A[0][0] = 64'sh8000000000000000;\nassign A[0][1] = 64'sh8000000000000000;\nassign A[0][2] = 64'sh8000000000000000;\nassign A[0][3] = 64'sh8000000000000000;\nassign A[0][4] = 64'sh8000000000000000;\nassign A[1][0] = 64'sh8000000000000000;\nassign A[1][1] = 64'sh8000000000000000;\nassign A[1][2] = 64'sh8000000000000000;\nassign A[1][3] = 64'sh8000000000000000;\nassign A[1][4] = 64'sh8000000000000000;\nassign A[2][0] = 64'sh8000000000000000;\nassign A[2][1] = 64'sh8000000000000000;\nassign A[2][2] = 64'd7;\nassign A[2][3] = 64'sh8000000000000000;\nassign A[2][4] = 64'sh8000000000000000;\nassign A[3][0] = 64'sh8000000000000000;\nassign A[3][1] = 64'sh8000000000000000;\nassign A[3][2] = 64'd7;\nassign A[3][3] = 64'sh8000000000000000;\nassign A[3][4] = 64'd8;\nassign A[4][0] = 64'sh8000000000000000;\nassign A[4][1] = 64'sh8000000000000000;\nassign A[4][2] = 64'sh8000000000000000;\nassign A[4][3] = 64'sh8000000000000000;\nassign A[4][4] = 64'd8;\n\n// Combinational max computation\ninteger k, i, j;\nalways @(*) begin\n    for (i = 0; i < C; i = i + 1) begin\n        for (j = 0; j < C; j = j + 1) begin\n            mult_out[i][j] = 64'sh8000000000000000;\n            for (k = 0; k < C; k = k + 1) begin\n                if (mult_A[i][k] != 64'sh8000000000000000 && mult_B[k][j] != 64'sh8000000000000000) begin\n                    if (($signed(mult_A[i][k]) + $signed(mult_B[k][j])) > $signed(mult_out[i][j])) begin\n                        mult_out[i][j] = mult_A[i][k] + mult_B[k][j];\n                    end\n                end\n            end\n        end\n    end\nend\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    integer m, n;\n    if (!rst_n) begin\n        done <= 1'b0;\n        state <= S_IDLE;\n        index <= 5'd0;\n        result_max <= 64'sh8000000000000000;\n        \n        // Initialize arrays\n        for (m = 0; m < C; m = m + 1) begin\n            for (n = 0; n < C; n = n + 1) begin\n                result[m][n] <= 64'sh8000000000000000;\n                base[m][n] <= 64'sh8000000000000000;\n                mult_A[m][n] <= 64'sh8000000000000000;\n                mult_B[m][n] <= 64'sh8000000000000000;\n            end\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    // Initialize result as identity matrix\n                    for (m = 0; m < C; m = m + 1) begin\n                        for (n = 0; n < C; n = n + 1) begin\n                            if (m == n) result[m][n] <= 64'd0;\n                            else result[m][n] <= 64'sh8000000000000000;\n                        end\n                    end\n                    \n                    // Initialize base to A\n                    for (m = 0; m < C; m = m + 1) begin\n                        for (n = 0; n < C; n = n + 1) begin\n                            base[m][n] <= A[m][n];\n                        end\n                    end\n                    \n                    index <= 5'd0;\n                    state <= S_CHECK;\n                end\n            end\n            \n            S_CHECK: begin\n                if (index >= 5'd29) state <= S_DONE;\n                else state <= S_MULT1;\n            end\n            \n            S_MULT1: begin\n                if (k_bits[index]) begin\n                    // Load result and base into multiplier\n                    for (m = 0; m < C; m = m + 1) begin\n                        for (n = 0; n < C; n = n + 1) begin\n                            mult_A[m][n] <= result[m][n];\n                            mult_B[m][n] <= base[m][n];\n                        end\n                    end\n                    state <= S_MULT1A;\n                end else begin\n                    state <= S_MULT2;\n                end\n            end\n            \n            S_MULT1A: begin\n                // Store multiplication to result\n                for (m = 0; m < C; m = m + 1) begin\n                    for (n = 0; n < C; n = n + 1) begin\n                        result[m][n] <= mult_out[m][n];\n                    end\n                end\n                state <= S_MULT2;\n            end\n            \n            S_MULT2: begin\n                // Load base and base into multiplier\n                for (m = 0; m < C; m = m + 1) begin\n                    for (n = 0; n < C; n = n + 1) begin\n                        mult_A[m][n] <= base[m][n];\n                        mult_B[m][n] <= base[m][n];\n                    end\n                end\n                state <= S_MULT2A;\n            end\n            \n            S_MULT2A: begin\n                // Store multiplication to base\n                for (m = 0; m < C; m = m + 1) begin\n                    for (n = 0; n < C; n = n + 1) begin\n                        base[m][n] <= mult_out[m][n];\n                    end\n                end\n                index <= index + 5'd1;\n                state <= S_CHECK;\n            end\n            \n            S_DONE: begin\n                // Find maximum result\n                result_max <= 64'sh8000000000000000;\n                for (m = 0; m < C; m = m + 1) begin\n                    for (n = 0; n < C; n = n + 1) begin\n                        if ($signed(result[m][n]) > $signed(result_max)) begin\n                            result_max <= result[m][n];\n                        end\n                    end\n                end\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule